import unittest
from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines(
            [
                make_shift("Ana", 9, 11),
                make_shift("Brisa", 9, 12),
                make_shift("Brisa", 9, 11, "tue"),
            ]
        )
        self.assertEqual(
            lines,
            [
                "Brisa: 2 shifts, 5.0 hours",
                "Ana: 1 shifts, 2.0 hours",
            ],
        )

    def test_one_decimal(self):
        shift = Shift("Ana", "mon", Span(540, 620))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Ana: 1 shifts, 1.3 hours"],
        )

    def test_empty(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 9, 10)])
